    string S;
    cin >> S;

    for (int a = 0; a <= 100; ++a) {
        for (int b = 0; b <= 100; ++b) {
            for (int c = 0; c <= 100; ++c) {
                // a 文字の A と b 文字の B と c 文字の C を連結したものが S と等しければ Yes
                if (string(a, 'A') + string(b, 'B') + string(c, 'C') == S) {
                    cout << "Yes" << endl;
                    return 0;
                }
            }
        }
    }

    // 等しくなるようなものがなければ No
    cout << "No" << endl;
    return 0;
}

