    int N = S.size();

    for (int i = 0; i < N; ++i) {
        if (S[i] == 'B') {
            // B の後にあるのは B か C のみでなければならない
            for (int j = i + 1; j < N; ++j) {
                if (S[j] != 'B' && S[j] != 'C') {
                    // 条件を満たさなければ No
                    cout << "No" << endl;
                    return 0;
                }
            }
        } else if (S[i] == 'C') {
            // C の後にあるのは C のみでなければならない
            for (int j = i + 1; j < N; ++j) {
                if (S[j] != 'C') {
                    // 条件を満たさなければ No
                    cout << "No" << endl;
                    return 0;
                }
            }
        }
    }

    cout << "Yes" << endl;
    return 0;
}

