    int N = S.size();

    for (int i = 0; i + 1 < N; ++i) {
        if (S[i] == 'B' && S[i + 1] != 'B' && S[i + 1] != 'C') {
            // B の直後にあるのは B か C のみでなければならない
            // 条件を満たさなければ No
            cout << "No" << endl;
            return 0;
        } else if (S[i] == 'C' && S[i + 1] != 'C') {
            // C の直後にあるのは C のみでなければならない
            // 条件を満たさなければ No
            cout << "No" << endl;
            return 0;
        }
    }

    cout << "Yes" << endl;
    return 0;
}

